    C c;

    function setUp() public { c = new C(address(this)); }

    function testFuzz_property(uint256 warpTime) public {
        vm.warp(warpTime);
        // The current owner (per c's own owner() getter) must be able to renounce
        // ownership; the reference succeeds and relinquishes, the mutant reverts
        // because its owner() always returns the zero address.
        vm.prank(c.owner());
        bool ok;
        try c.renounceOwnership() {
            ok = true;
        } catch {
            ok = false;
        }
        assertTrue(ok, "the current owner must be able to renounce ownership");
    }
}

