pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }

    function testFuzz_property(address newOwner) public {
        vm.assume(newOwner != address(0));

        // The current owner can always transfer ownership to any non-zero address.
        vm.prank(c.owner());
        bool ok;
        try c.transferOwnership(newOwner) {
            ok = true;
        } catch {
            ok = false;
        }

        // General rule: after a successful ownership transfer initiated by the
        // real owner, c.owner() reports exactly the new owner (non-zero).
        assertTrue(ok && c.owner() == newOwner);
    }
}

