pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(address caller) public {
        vm.assume(caller != address(0));
        // The legitimate owner renounces ownership.
        c.renounceOwnership();
        // An arbitrary (fuzzed) caller attempts an owner-only action afterwards.
        vm.prank(caller);
        bool ok;
        try c.setCaller(caller) { ok = true; } catch { ok = false; }
        // Rule: once ownership is renounced, NO caller can execute owner-only actions.
        assertTrue(!ok);
    }
}

