pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(address(this)); }

    function testFuzz_property(address newOwner) public {
        vm.assume(newOwner != address(0));
        vm.assume(newOwner != address(this));

        // Current (deployer) owner transfers ownership away to a fuzzed new owner.
        vm.prank(address(this));
        c.transferOwnership(newOwner);

        // The previous owner (this test contract) must no longer hold owner power:
        // owner-only actions from it must revert.
        vm.prank(address(this));
        bool ok;
        try c.setCaller(address(this)) {
            ok = true;
        } catch {
            ok = false;
        }

        // Reference: previous owner is stripped of owner-only rights (call reverts).
        // Mutant: owner() returns the caller, so the previous owner still succeeds.
        assertTrue(!ok, "previous owner must not be able to call owner-only functions after transferring ownership");
    }
}

