pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public {
        c = new C(address(this));
    }

    function testFuzz_property(address newOwner) public {
        // newOwner must be admissible: non-zero, and different from current owner (so a real transfer happens)
        vm.assume(newOwner != address(0));
        vm.assume(newOwner != address(this));

        // drive c through transferOwnership from the current owner (deployer = address(this))
        vm.prank(address(this));
        c.transferOwnership(newOwner);

        // General rule: after transferOwnership(x), owner() == x (for any admissible x).
        // Reference C satisfies this for all inputs; mutant M sets owner to address(0), breaking it.
        assertTrue(c.owner() == newOwner);
    }
}

