pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }

    function testFuzz_property(address newOwner, address nextOwner) public {
        vm.assume(newOwner != address(0));
        vm.assume(nextOwner != address(0));

        // current owner (this contract, deployed with ownership) hands over to newOwner
        c.transferOwnership(newOwner);

        // The new owner must now be able to transfer ownership onward.
        // Rule: any non-zero newOwner appointed via transferOwnership can exercise
        // the owner-only transferOwnership entry point afterwards.
        vm.prank(newOwner);
        bool ok;
        try c.transferOwnership(nextOwner) {
            ok = true;
        } catch {
            ok = false;
        }
        assertTrue(ok);
    }
}
